const d = $('Complaint Webhook').first().json.body;

const ticketId    = d.id            || '—';
const name        = d.name          || 'Not provided';
const email       = d.email         || '';
const phone       = d.phone         || 'Not provided';
const orderNumber = d.order_number  || 'Not provided';
const category    = d.category      || 'Other';
const subject     = d.subject       || '(no subject)';
const message     = d.message       || '';

const now = new Date().toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });

const LOGO_URL = 'https://yellowfeather.netlify.app/logo-landscape.png';

const html = `<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/></head>
<body style="font-family:Arial,sans-serif;background:#f4f4f4;margin:0;padding:0;">
<div style="max-width:600px;margin:32px auto;background:#fff;border-radius:10px;overflow:hidden;box-shadow:0 2px 16px rgba(0,0,0,0.10);">
  <div style="background:#1a1a2e;padding:24px 40px;display:flex;align-items:center;justify-content:space-between;">
    <img src="${LOGO_URL}" alt="Yellow Feather Books" style="height:44px;object-fit:contain;"/>
    <div style="text-align:right;"><span style="color:#F5B800;font-size:15px;font-weight:700;display:block;">New Complaint #${ticketId}</span><span style="color:#aaa;font-size:11px;">${now}</span></div>
  </div>
  <div style="padding:32px 40px;">
    <div style="background:#f9f7f2;border-left:4px solid #C9922A;border-radius:6px;padding:16px 20px;margin-bottom:28px;">
      <div style="font-size:11px;color:#999;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:6px;">${category}</div>
      <div style="font-size:20px;font-weight:700;color:#1a1a2e;">${subject}</div>
    </div>
    <table style="width:100%;border-collapse:collapse;font-size:14px;margin-bottom:24px;">
      <tr><td style="padding:10px 0;color:#666;width:140px;">Name</td><td style="padding:10px 0;font-weight:600;color:#1a1a2e;">${name}</td></tr>
      <tr style="border-top:1px solid #e5e0d8;"><td style="padding:10px 0;color:#666;">Email</td><td style="padding:10px 0;"><a href="mailto:${email}" style="color:#C9922A;font-weight:600;text-decoration:none;">${email}</a></td></tr>
      <tr style="border-top:1px solid #e5e0d8;"><td style="padding:10px 0;color:#666;">Phone</td><td style="padding:10px 0;font-weight:600;color:#1a1a2e;">${phone}</td></tr>
      <tr style="border-top:1px solid #e5e0d8;"><td style="padding:10px 0;color:#666;">Order #</td><td style="padding:10px 0;font-weight:600;color:#1a1a2e;">${orderNumber}</td></tr>
      <tr style="border-top:1px solid #e5e0d8;"><td style="padding:10px 0;color:#666;vertical-align:top;">Message</td><td style="padding:10px 0;color:#555;">${message}</td></tr>
    </table>
    <p style="font-size:13px;color:#888;line-height:1.7;margin:0;">This ticket was submitted through the <strong>Customer Care</strong> form on yellowfeatherbooks.com. Open the admin panel's Customer Care section to respond and resolve it.</p>
  </div>
  <div style="background:#f5f0e8;padding:16px 40px;text-align:center;font-size:11px;color:#888;border-top:1px solid #e5e0d8;">Yellow Feather Books &nbsp;·&nbsp; Customer Care &nbsp;·&nbsp; <a href="mailto:${email}" style="color:#C9922A;text-decoration:none;">Reply to ${email}</a></div>
</div></body></html>`;

return [{ json: { ...d, html, ticketId, subject, customerEmail: email } }];
